import{z as n,x as p,o as t,c as A,q as s,j as E,D as r,d as P,s as i,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"PCP 与不可近似","description":"","frontmatter":{"title":"PCP 与不可近似","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/pcp-inapproximability.md","filePath":"cs/pcp-inapproximability.md","lastUpdated":1791413859000}'),B={name:"cs/pcp-inapproximability.md"};function d(C,a,m,h,N,c){const o=p("Mermaid");return t(),A("div",null,[a[2]||(a[2]=s('<h1 id="pcp-与不可近似" tabindex="-1">PCP 与不可近似 <a class="header-anchor" href="#pcp-与不可近似" aria-label="Permalink to &quot;PCP 与不可近似&quot;">​</a></h1><div class="epigraph"><p>NP 证明可以写成：验证者只随机看常数个比特，仍有完备与可靠；由此，许多优化问题连近似比都被钉死。</p><footer>—— 据 Arora, Lund, Motwani, Sudan and Szegedy, 1998；Arora and Barak 整理</footer></div><p>上一课<a href="/cs/interactive-proofs">IP = PSPACE</a> 是多轮交谈。PCP 把「随机局部查」收成对 NP 的刻画：\\(\\mathrm{NP}=\\mathrm{PCP}(\\log n, O(1))\\)。缺口不是再做一个交互类，而是<strong>不可近似</strong>：若能把 Max-3SAT 近似到 \\(7/8+\\varepsilon\\) 以内，则会把 NP 放进 P。主干<a href="/cs/approximation-ratio">近似比</a> 给了 \\(\\rho\\) 的定义，未给 PCP 下界。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>PCP 验证者：掷 \\(O(\\log n)\\) 硬币，查证明的 \\(O(1)\\) 位，多项式时间，Yes 几乎总接受，No 任意证明几乎总拒。ALMSS 定理：这正是 NP。直觉：把 SAT 证明编码成局部可测的对象（多项式、展开图），错误被放大。本课不构造。</p><p>不可近似：从 PCP 验证的接受概率做成优化目标。Max-3SAT、团、顶点覆盖的缝隙（gap）归约，使「近似到某比」等于判定 NP。Hastad 的 \\(7/8\\) 是紧的课堂钉子，点名。</p><h3 id="pcp-不是-ip-的别名" tabindex="-1">PCP 不是 IP 的别名 <a class="header-anchor" href="#pcp-不是-ip-的别名" aria-label="Permalink to &quot;PCP 不是 IP 的别名&quot;">​</a></h3><p>PCP 验证者不与证明者交谈，证明是字面量，只是不读完。IP 的证明者自适应。类：PCP 刻画 NP，IP 刻画 PSPACE。</p><p><span class="marginnote">ALMSS 1998（PCP 定理）。Arora–Barak 第 11、22 章。Hastad 1997 最优不可近似。本课要用法：缝隙归约，不写傅里叶分析。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>陈述 PCP 定理。展示缝隙：Yes 公式可满足，No 公式任意赋值只满足 \\(\\lt s\\) 的子句，\\(s\\lt 1\\) 常数。多项式归约若保持缝隙，则近似算法会区分 SAT。对照 Cook–Levin 的「恰好可满足」：PCP 把恰好变成统计上的远离。</p><p><span class="marginnote">数字实例：Max-3SAT 的随机赋值就能满足每个子句的 7/8（每个 3 子句只被一种全假组合骗过）。Hastad 定理说的正是：想稳定超过 7/8，哪怕只超一小点 \\(\\varepsilon\\)，就等价于解决了 NP——所以 7/8 这条线是「白送」的上限。</span></p>',12)),(t(),E(l,null,{default:r(()=>[i(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20NP%5B%22NP%22%5D%20--%3E%20PCP%5B%22PCP%20%E5%B1%80%E9%83%A8%E6%9F%A5%E8%AF%81%E6%98%8E%22%5D%0A%20%20PCP%20--%3E%20GAP%5B%22%E7%BC%9D%E9%9A%99%203SAT%22%5D%0A%20%20GAP%20--%3E%20INAPP%5B%22%E8%BF%91%E4%BC%BC%E6%AF%94%E4%B8%8B%E7%95%8C%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[P(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[P("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"有了缝隙，近似不再是「差一点的 NPC」。UGC 等更强假设收紧常数，本课不依赖。算法课的贪心比若优于 PCP 下界，只可能是对特例，或假设崩溃。",-1)),a[5]||(a[5]=e("p",null,"查询次数与缝隙大小互易；常数查询是定理的锋刃。",-1)),a[6]||(a[6]=e("p",null,"查询 \\(O(1)\\) 比特把「读整份证明」换成抽样。缝隙 3SAT 的 Yes/No 实例在子句满足比例上分开常数。Hastad 的 \\(7/8\\)：随机赋值已达 \\(7/8\\)，更好的多项式近似除非 \\(P=NP\\)。近似比课的贪心上界若与此冲突，只可能在特殊图族。",-1)),(t(),E(l,null,{default:r(()=>[i(o,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E8%BE%93%E5%85%A5%203SAT%20%E5%85%AC%E5%BC%8F%20x%22%5D%20--%3E%20R%5B%22%E5%BD%92%E7%BA%A6%E5%87%BD%E6%95%B0%20f%EF%BC%88%E5%A4%9A%E9%A1%B9%E5%BC%8F%E6%97%B6%E9%97%B4%EF%BC%89%22%5D%0A%20%20R%20--%3E%7Cx%20%E6%98%AF%20Yes%20%E5%AE%9E%E4%BE%8B%7C%20Y%5B%22f(x)%EF%BC%9A%E5%AD%90%E5%8F%A5%20100%25%20%E5%8F%AF%E6%BB%A1%E8%B6%B3%22%5D%0A%20%20R%20--%3E%7Cx%20%E6%98%AF%20No%20%E5%AE%9E%E4%BE%8B%7C%20N%5B%22f(x)%EF%BC%9A%E4%BB%BB%E4%BD%95%E8%B5%8B%E5%80%BC%E5%8F%AA%E6%BB%A1%E8%B6%B3%20%3C%20s%20%E6%AF%94%E4%BE%8B%22%5D%0A%20%20Y%20--%3E%20A%5B%22%E8%BF%91%E4%BC%BC%E7%AE%97%E6%B3%95%E8%8B%A5%E4%BF%9D%E8%AF%81%20%3E%20s%20%E6%AF%94%E4%BE%8B%22%5D%0A%20%20N%20--%3E%20A%0A%20%20A%20--%3E%20VERDICT%5B%22%E5%B0%B1%E8%83%BD%E5%8C%BA%E5%88%86%20Yes%2FNo%EF%BC%8C%E7%AD%89%E4%BA%8E%E8%A7%A3%E5%87%BA%20NP%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[P(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=s('<p>这张图回答的问题是：「缝隙归约」凭什么把近似算法变成 NP 判定器？归约不是保持答案不变，而是把差距拉到常数宽：Yes 实例映成完美可满足，No 实例映成连最优解都够不到线 \\(s\\)。一个能稳定跨过这条线的近似算法，就顺带完成了 SAT 判定。</p><p><span class="marginnote">直觉类比：普通归约像用尺子量出「行/不行」，缝隙归约则是把两堆货物先分装到相差一米的两个货架上——之后哪怕用一把误差很大的粗尺子，也能立刻看出谁在哪边。近似算法就是那把「粗尺子」，缝隙保证了粗尺也够用。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证 PCP，不引入 Unique Games。不把 LDPC 的局部校验与 PCP 验证混为一谈（编码课后头）。后课默认：谈不可近似，先问是否 PCP 缝隙。下一课非均匀：电路。</p><p><span class="marginnote">常见误区：以为「不可近似 = 没有启发式可用」。实际上它只禁止多项式时间内把近似比推过某条线——工程上的局部搜索、整数规划求解器照样能在多数实例上跑得很好；下界约束的是最坏情形的理论保证，不是实践手感。</span></p><p>PCP 把证明写成可随机局部查的对象，从而把「恰好 SAT」加成「满足比例的缝隙」。近似算法的 \\(\\rho\\) 从此可能有 NP 硬度，不只是启发式好坏。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(\\mathrm{NP}=\\mathrm{PCP}(\\log n,O(1))\\)：随机局部查证明。</li><li>缝隙归约给出近似比的 NP 硬度。</li><li>与 IP 分工：NP vs PSPACE。</li><li>出处：Arora et al., 1998；Hastad；Arora and Barak。</li></ul>',8))])}const S=n(B,[["render",d]]);export{f as __pageData,S as default};
